<?php declare(strict_types=1);use FastWebsite\Core\View;$value=static fn(string$f):string=>(string)($values[$f]??'');$editing=is_int($publicationId);$published=$editing&&$currentStatus==='published';$action=$editing?$baseUrl.'admin/research/publications/'.$publicationId:$baseUrl.'admin/research/publications';?>
<section class="admin-page-heading"><div><p class="eyebrow"><?=$published?'Live publication':($editing?'Publication revision':'New publication draft')?></p><h1><?=$editing?'Edit publication':'Create publication'?></h1><p><?=$published?'The public citation stays online while saved changes apply immediately.':'Save the bibliographic record, add its authors, then publish.'?></p></div><a class="button button-secondary" href="<?=View::escape($baseUrl)?>admin/research/publications<?=$editing?'/'.$publicationId:''?>">Cancel</a></section><?php if($errors!==[]):?><div class="form-alert"><strong>Please correct the following:</strong><ul><?php foreach($errors as$error):?><li><?=View::escape($error)?></li><?php endforeach;?></ul></div><?php endif;?><?php if($published):?><div class="success-alert live-edit-notice"><strong>Editing published content.</strong> Saved changes remain public.</div><?php endif;?><form class="content-form" method="post" action="<?=View::escape($action)?>"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>">
<section class="form-section"><div class="form-section-heading"><h2>Publication identity</h2></div><div class="form-grid"><div class="form-field span-2"><label for="title">Publication title *</label><textarea id="title" name="title" rows="3" required><?=View::escape($value('title'))?></textarea></div><div class="form-field"><label for="publication_type_id">Publication type *</label><select id="publication_type_id" name="publication_type_id" required><?php foreach($types as$type):?><option value="<?=(int)$type['id']?>"<?=$value('publication_type_id')===(string)$type['id']?' selected':''?>><?=View::escape($type['name'])?></option><?php endforeach;?></select></div><div class="form-field"><label for="access_type">Access</label><select id="access_type" name="access_type"><?php foreach(['open_access'=>'Open access','subscription'=>'Subscription','restricted'=>'Restricted','unknown'=>'Unknown']as$key=>$label):?><option value="<?=$key?>"<?=$value('access_type')===$key?' selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="form-field span-2"><label for="slug">Public URL</label><input id="slug" name="slug" maxlength="320" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" value="<?=View::escape($value('slug'))?>"><p class="field-guidance">Leave blank to generate from the title.</p></div></div></section>
<section class="form-section"><div class="form-section-heading"><h2>Bibliographic details</h2></div><div class="form-grid"><div class="form-field"><label for="journal_name">Journal or source</label><input id="journal_name" name="journal_name" maxlength="255" value="<?=View::escape($value('journal_name'))?>"></div><div class="form-field"><label for="publisher">Publisher</label><input id="publisher" name="publisher" maxlength="255" value="<?=View::escape($value('publisher'))?>"></div><div class="form-field"><label for="publication_year">Publication year</label><input id="publication_year" name="publication_year" type="number" min="1800" max="<?=date('Y')+2?>" value="<?=View::escape($value('publication_year'))?>"></div><div class="form-field"><label for="publication_date">Publication date</label><input id="publication_date" name="publication_date" type="date" value="<?=View::escape($value('publication_date'))?>"></div><div class="form-field"><label for="volume">Volume</label><input id="volume" name="volume" maxlength="50" value="<?=View::escape($value('volume'))?>"></div><div class="form-field"><label for="issue">Issue</label><input id="issue" name="issue" maxlength="50" value="<?=View::escape($value('issue'))?>"></div><div class="form-field"><label for="page_range">Pages</label><input id="page_range" name="page_range" maxlength="50" value="<?=View::escape($value('page_range'))?>"></div><div class="form-field"><label for="isbn">ISBN</label><input id="isbn" name="isbn" maxlength="50" value="<?=View::escape($value('isbn'))?>"></div><div class="form-field"><label for="doi">DOI</label><input id="doi" name="doi" maxlength="255" value="<?=View::escape($value('doi'))?>" placeholder="10.1000/example"></div><div class="form-field"><label for="external_url">External publication URL</label><input id="external_url" name="external_url" type="url" maxlength="500" value="<?=View::escape($value('external_url'))?>" placeholder="https://"></div></div></section>
<section class="form-section"><div class="form-section-heading"><h2>Research links</h2><p>Optional. Department-scoped editors must link a project or unit they can manage.</p></div><div class="form-grid"><div class="form-field"><label for="project_id">Related project</label><select id="project_id" name="project_id"><option value="">No linked project</option><?php foreach($projects as$p):?><option value="<?=(int)$p['id']?>"<?=$value('project_id')===(string)$p['id']?' selected':''?>><?=View::escape($p['title'])?></option><?php endforeach;?></select></div><div class="form-field"><label for="research_unit_id">Related research unit</label><select id="research_unit_id" name="research_unit_id"><option value="">No linked research unit</option><?php foreach($researchUnits as$unit):?><option value="<?=(int)$unit['id']?>"<?=$value('research_unit_id')===(string)$unit['id']?' selected':''?>><?=View::escape($unit['name'])?></option><?php endforeach;?></select></div></div></section>
<section class="form-section"><div class="form-section-heading"><h2>Abstract and citation</h2></div><div class="form-grid"><div class="form-field span-2"><label for="abstract">Abstract</label><textarea id="abstract" name="abstract" rows="8"><?=View::escape($value('abstract'))?></textarea></div><div class="form-field span-2"><label for="citation_text">Preferred citation</label><textarea id="citation_text" name="citation_text" rows="5"><?=View::escape($value('citation_text'))?></textarea></div></div></section><?php if($editing):?><section class="form-section"><div class="form-field"><label for="revision_note">Revision note</label><textarea id="revision_note" name="revision_note" rows="3"><?=View::escape($revisionNote)?></textarea></div></section><?php endif;?><div class="form-actions"><?php if($published):?><button class="button button-primary" type="submit">Save published changes</button><?php else:?><button class="button <?=$canPublishDirectly?'button-secondary':'button-primary'?>" type="submit" name="submit_action" value="save"><?=$editing?'Save revision':'Create draft and add authors'?></button><?php if($canPublishDirectly):?><button class="button button-primary" type="submit" name="submit_action" value="publish">Save and publish</button><?php endif;?><?php endif;?><a class="button button-secondary" href="<?=View::escape($baseUrl)?>admin/research/publications<?=$editing?'/'.$publicationId:''?>">Cancel</a></div></form>
